//! Regressions for review findings on the tolerant reader. Each test patches
//! a committed file of testdata/anomalous/files (generated by
//! crates/unforge-testgen) the way the finding describes.

use std::path::PathBuf;

use unforge_elf::{
    Choice, Class, DiagnosticKind, DynamicSymbolCount, ElfFile, InferenceSubject, LayoutSource,
};

fn file(rel: &str) -> Vec<u8> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../testdata/anomalous/files")
        .join(rel);
    std::fs::read(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

fn put16(d: &mut [u8], at: usize, v: u16) {
    d[at..at + 2].copy_from_slice(&v.to_le_bytes());
}
fn put64(d: &mut [u8], at: usize, v: u64) {
    d[at..at + 8].copy_from_slice(&v.to_le_bytes());
}
fn get64(d: &[u8], at: usize) -> u64 {
    u64::from_le_bytes(d[at..at + 8].try_into().unwrap())
}
/// Offset of program header `i` field `field` (ELF64, e_phoff 0x40).
fn ph(i: usize, field: usize) -> usize {
    0x40 + i * 56 + field
}
const P_TYPE: usize = 0;
const P_OFFSET: usize = 8;
const P_VADDR: usize = 16;
const P_PADDR: usize = 24;
const P_FILESZ: usize = 32;
const P_MEMSZ: usize = 40;
const P_ALIGN: usize = 48;

fn kinds(d: &[u8]) -> Vec<DiagnosticKind> {
    ElfFile::parse(d)
        .unwrap()
        .audit()
        .diagnostics
        .into_iter()
        .map(|d| d.kind)
        .collect()
}

/// EI_CLASS = 1 plus e_shoff bytes that read as a perfect ELF32 header
/// (`e_ehsize 52, e_phentsize 32, e_phnum n, e_shentsize 40`).
fn lying_class(rel: &str, phnum32: u16, zero_ehsize: bool) -> Vec<u8> {
    let mut d = file(rel);
    d[4] = 1;
    for (k, v) in [52u16, 32, phnum32, 40].into_iter().enumerate() {
        put16(&mut d, 0x28 + 2 * k, v);
    }
    if zero_ehsize {
        put16(&mut d, 0x34, 0);
    }
    d
}

/// tolerance-layout-claim-beats-kernel (x86-64 case): the kernel-checked
/// ELF64 reading wins over the claim plus kernel-ignored bytes, and the
/// claimed ELF32 reading is listed as a viable alternative.
#[test]
fn kernel_reading_beats_lying_class_x86_64() {
    let d = lying_class("x86_64/s00-baseline.elf", 0, false);
    let f = ElfFile::parse(&d).unwrap();
    assert_eq!(f.header().class, Class::Elf64);
    assert_eq!(f.header().phoff, 0x40);
    assert!(f.program_headers().unwrap().len() > 1);
    assert_eq!(f.layout().source, LayoutSource::Machine);
    let a = f.audit();
    assert!(a.diagnostics.iter().any(|d| matches!(
        d.kind,
        DiagnosticKind::ClassMismatch {
            claimed: 1,
            used: Class::Elf64
        }
    )));
    let inf = a
        .inferences()
        .find(|i| i.subject == InferenceSubject::Layout)
        .expect("layout inference");
    assert!(inf.alternatives.iter().any(|alt| matches!(
        alt.choice,
        Choice::Layout {
            class: Class::Elf32,
            ..
        }
    ) && alt.viable));
    assert!(a.ambiguous);
}

/// tolerance-layout-claim-beats-kernel (aarch64, e1: ran on the real
/// kernel) and tolerance-layout-ident-never-ambiguous: the claim no longer
/// wins a tie silently.
#[test]
fn kernel_reading_beats_lying_class_aarch64() {
    let d = lying_class("aarch64/s00-baseline.elf", 2, true);
    let f = ElfFile::parse(&d).unwrap();
    assert_eq!(f.header().class, Class::Elf64);
    let phdrs = f.program_headers().unwrap();
    assert!(phdrs.iter().all(|p| p.p_type != 0x464c_457f));
    let k = kinds(&d);
    assert!(
        k.iter()
            .any(|k| matches!(k, DiagnosticKind::ClassMismatch { .. }))
    );
    assert!(k.iter().any(
        |k| matches!(k, DiagnosticKind::Inferred(i) if i.subject == InferenceSubject::Layout)
    ));
    // e_ehsize 0 makes the ELF64 reading inconsistent: that is reported.
    assert!(k.iter().any(|k| matches!(
        k,
        DiagnosticKind::LayoutInconsistent {
            class: Class::Elf64,
            ..
        }
    )));
}

/// tolerance-layout-ident-never-ambiguous: when the header supports two
/// layouts equally and only EI_CLASS decides, the claim is used but
/// recorded as an unconfirmed inference with a viable alternative.
#[test]
fn claim_that_only_breaks_a_tie_is_an_inference() {
    // ET_REL x86-64 (EM_X86_64 is used in both classes on Linux), no
    // program headers or sections, header sizes valid in both readings.
    let mut d = vec![0u8; 64];
    d[..8].copy_from_slice(&[0x7f, b'E', b'L', b'F', 2, 1, 1, 0]);
    put16(&mut d, 0x10, 1);
    put16(&mut d, 0x12, 62);
    d[0x14] = 1;
    for (k, v) in [52u16, 32, 0, 40].into_iter().enumerate() {
        put16(&mut d, 0x28 + 2 * k, v);
    }
    put16(&mut d, 0x34, 64);
    put16(&mut d, 0x36, 56);
    put16(&mut d, 0x3a, 64);
    let f = ElfFile::parse(&d).unwrap();
    assert_eq!(f.header().class, Class::Elf64);
    assert_eq!(f.layout().source, LayoutSource::IdentUnconfirmed);
    assert!(f.layout().is_inferred());
    assert!(f.layout().viable_alternatives().count() >= 1);
    assert!(f.is_ambiguous());
    // The well-formed baseline is still read from its identification bytes.
    let b = file("x86_64/s00-baseline.elf");
    let f = ElfFile::parse(&b).unwrap();
    assert_eq!(f.layout().source, LayoutSource::Ident);
    assert!(!f.audit().inferred);
}

/// tolerance-memmap-byte-granular (e3, ran on the real kernel): e_entry in
/// the page slack below the RX segment is mapped by the kernel.
#[test]
fn entry_in_page_slack_is_mapped() {
    let mut d = file("aarch64/s00-baseline.elf");
    for f in [P_OFFSET, P_VADDR, P_PADDR] {
        let v = get64(&d, ph(2, f));
        put64(&mut d, ph(2, f), v + 0x10);
    }
    for f in [P_FILESZ, P_MEMSZ] {
        let v = get64(&d, ph(2, f));
        put64(&mut d, ph(2, f), v - 0x10);
    }
    let f = ElfFile::parse(&d).unwrap();
    let entry = f.header().entry;
    assert_eq!(entry, 0x211c10);
    let b = f.memory_map().backing(entry).expect("kernel maps the page");
    assert_eq!(
        (b.segment, b.file_offset, b.in_segment),
        (2, Some(0x1c10), false)
    );
    // The byte-granular reading (page size 1) does not map it.
    assert!(f.memory_map_with_page_size(1).backing(entry).is_none());
    let k = kinds(&d);
    assert!(
        !k.iter()
            .any(|k| matches!(k, DiagnosticKind::EntryNotExecutable { .. }))
    );
    assert!(k.iter().any(|k| matches!(
        k,
        DiagnosticKind::EntryInPageSlack {
            entry: 0x211c10,
            segment: 2,
            ..
        }
    )));
    assert!(k.iter().any(
        |k| matches!(k, DiagnosticKind::Inferred(i) if i.subject == InferenceSubject::PageSize)
    ));
}

/// tolerance-memmap-byte-granular (e4): a later PT_LOAD replaces the whole
/// shared page of an earlier one.
#[test]
fn later_load_replaces_whole_pages() {
    let mut d = file("aarch64/s00-baseline.elf");
    put64(&mut d, ph(8, P_TYPE), 1 | (4u64 << 32)); // PT_LOAD, PF_R
    put64(&mut d, ph(8, P_OFFSET), 0x2c80);
    put64(&mut d, ph(8, P_VADDR), 0x201c80);
    put64(&mut d, ph(8, P_PADDR), 0x201c80);
    put64(&mut d, ph(8, P_FILESZ), 0x10);
    put64(&mut d, ph(8, P_MEMSZ), 0x10);
    put64(&mut d, ph(8, P_ALIGN), 0x1000);
    let f = ElfFile::parse(&d).unwrap();
    let b = f.memory_map().backing(0x201000).unwrap();
    assert_eq!(
        (b.segment, b.file_offset, b.overrides.as_slice()),
        (8, Some(0x2000), &[1][..])
    );
    let k = kinds(&d);
    assert!(k.iter().any(|k| matches!(
        k,
        DiagnosticKind::LoadsOverlap {
            earlier: 1,
            later: 8,
            start: 0x201000,
            end: 0x202000
        }
    )));
    assert!(k.iter().any(
        |k| matches!(k, DiagnosticKind::Inferred(i) if i.subject == InferenceSubject::PageSize)
    ));
}

/// tolerance-ptload-kernel-fatal-silent (e6, e7: both SIGSEGV on the real
/// kernel): reported by the audit itself, not only by the kernel model.
#[test]
fn kernel_fatal_ptload_fields_are_reported() {
    let mut e6 = file("aarch64/s00-baseline.elf");
    let fs = get64(&e6, ph(4, P_FILESZ));
    put64(&mut e6, ph(4, P_MEMSZ), fs - 8);
    assert!(
        kinds(&e6)
            .iter()
            .any(|k| matches!(k, DiagnosticKind::FileszExceedsMemsz { index: 4, .. }))
    );

    let mut e7 = file("aarch64/s00-baseline.elf");
    let o = get64(&e7, ph(4, P_OFFSET));
    put64(&mut e7, ph(4, P_OFFSET), o + 8);
    put64(&mut e7, ph(4, P_ALIGN), 0);
    assert!(kinds(&e7).iter().any(|k| matches!(
        k,
        DiagnosticKind::OffsetNotPageCongruent {
            index: 4,
            page_size: 4096,
            ..
        }
    )));
    // The baseline has neither.
    let k = kinds(&file("aarch64/s00-baseline.elf"));
    assert!(!k.iter().any(|k| matches!(
        k,
        DiagnosticKind::FileszExceedsMemsz { .. } | DiagnosticKind::OffsetNotPageCongruent { .. }
    )));
}

/// tolerance-dynsym-not-crosschecked: the loader's table is read through
/// PT_DYNAMIC, also without section headers, and a decoy SHT_DYNSYM is
/// reported.
#[test]
fn dynamic_symbols_come_from_pt_dynamic() {
    let f0 = file("x86_64/d02-sstrip.elf");
    let f = ElfFile::parse(&f0).unwrap();
    assert!(f.section_headers().unwrap().is_empty());
    let ds = f.dynamic_symbols().unwrap();
    assert!(matches!(ds.count, DynamicSymbolCount::Hash { nchain: 1 }));
    assert_eq!(ds.len(), 1);

    let base = file("x86_64/d00-baseline.elf");
    assert!(kinds(&base).iter().all(|k| !matches!(
        k,
        DiagnosticKind::DynamicSymbolsMismatch { .. } | DiagnosticKind::FirstSymbolNotNull { .. }
    )));
    // Shift the .dynsym header (section 1) by one entry.
    let f = ElfFile::parse(&base).unwrap();
    let sh = f.header().shoff as usize + 64;
    let mut d = base.clone();
    for (off, delta) in [(16usize, 24i64), (24, 24), (32, -24)] {
        let v = get64(&d, sh + off) as i64 + delta;
        put64(&mut d, sh + off, v as u64);
    }
    let k = kinds(&d);
    assert!(
        k.iter().any(|k| matches!(
            k,
            DiagnosticKind::DynamicSymbolsMismatch {
                section: 1,
                dynamic: 0x270,
                section_value: 0x288,
                ..
            }
        )),
        "{k:?}"
    );
}

/// DT_GNU_HASH alone: the count comes from the chains and is confirmed by
/// SHT_DYNSYM, so no inference.
#[test]
fn gnu_hash_count_confirmed_by_section() {
    let mut d = file("x86_64/d00-baseline.elf");
    let f = ElfFile::parse(&d).unwrap();
    let off = f.dynamic().unwrap().file_offset as usize;
    // Turn DT_HASH (4) into DT_DEBUG (21).
    let mut i = off;
    while get64(&d, i) != 0 {
        if get64(&d, i) == 4 {
            put64(&mut d, i, 21);
        }
        i += 16;
    }
    let f = ElfFile::parse(&d).unwrap();
    let ds = f.dynamic_symbols().unwrap();
    assert!(matches!(ds.count, DynamicSymbolCount::GnuHash { count: 1 }));
    assert!(
        !f.inferences()
            .iter()
            .any(|i| i.subject == InferenceSubject::DynamicSymbolCount)
    );
}

// ---------------------------------------------------------------------------
// Work bounds: inputs that used to cost O(sections^2).
// ---------------------------------------------------------------------------

fn shdr(ty: u32, link: u32, off: u64, size: u64, ent: u64) -> Vec<u8> {
    let mut v = vec![0u8; 64];
    v[4..8].copy_from_slice(&ty.to_le_bytes());
    v[24..32].copy_from_slice(&off.to_le_bytes());
    v[32..40].copy_from_slice(&size.to_le_bytes());
    v[40..44].copy_from_slice(&link.to_le_bytes());
    v[56..64].copy_from_slice(&ent.to_le_bytes());
    v
}

/// ELF64 LE ET_REL x86-64 with these section headers at 0x40.
fn with_sections(shdrs: &[Vec<u8>], shstrndx: u16, tail: &[u8]) -> Vec<u8> {
    let mut d = vec![0u8; 64];
    d[..8].copy_from_slice(&[0x7f, b'E', b'L', b'F', 2, 1, 1, 0]);
    put16(&mut d, 0x10, 1);
    put16(&mut d, 0x12, 62);
    d[0x14] = 1;
    put64(&mut d, 0x28, 64);
    put16(&mut d, 0x34, 64);
    put16(&mut d, 0x36, 56);
    put16(&mut d, 0x3a, 64);
    put16(&mut d, 0x3c, shdrs.len() as u16);
    put16(&mut d, 0x3e, shstrndx);
    for s in shdrs {
        d.extend_from_slice(s);
    }
    d.extend_from_slice(tail);
    d
}

fn timed(what: &str, f: impl FnOnce()) {
    let t = std::time::Instant::now();
    f();
    let e = t.elapsed();
    assert!(e < std::time::Duration::from_secs(3), "{what}: {e:?}");
}

/// zerocopy-1 / safety-xindex-many-quadratic.
#[test]
fn many_shndx_sections_stay_linear() {
    let n = 30_000;
    let mut s = vec![
        shdr(0, 0, 0, 0, 0),
        shdr(18, 0, 0, 0, 0),
        shdr(18, 0, 0, 0, 0),
    ];
    s.extend((3..n).map(|_| shdr(2, 0, 0, 0, 24)));
    let d = with_sections(&s, 0, &[]);
    let f = ElfFile::parse(&d).unwrap();
    timed("symbol_tables + audit", || {
        assert_eq!(f.symbol_tables().unwrap().count(), n - 3);
        f.audit();
    });
}

/// zerocopy-2 / safety-audit-strtab-alternatives-quadratic.
#[test]
fn many_tables_linked_to_a_non_strtab_stay_linear() {
    let n = 30_000;
    let mut s = vec![shdr(0, 0, 0, 0, 0), shdr(1, 0, 0, 0, 0)];
    s.extend((2..n).map(|_| shdr(2, 1, 0, 0, 24)));
    let d = with_sections(&s, 0, &[]);
    let f = ElfFile::parse(&d).unwrap();
    timed("audit", || {
        f.audit();
    });
}

/// zerocopy-3: every section names the same 1 MiB string.
#[test]
fn section_by_name_does_not_read_long_names() {
    let n = 4000usize;
    let mut name = vec![b'A'; 1 << 20];
    name.push(0);
    let strtab_off = 64 + 64 * n as u64;
    let mut s = vec![
        shdr(0, 0, 0, 0, 0),
        shdr(3, 0, strtab_off, name.len() as u64, 0),
    ];
    s.extend((2..n).map(|_| shdr(1, 0, 0, 0, 0)));
    let d = with_sections(&s, 1, &name);
    let f = ElfFile::parse(&d).unwrap();
    let t = std::time::Instant::now();
    for _ in 0..20 {
        assert!(f.section_by_name(b".text").is_none());
    }
    assert!(
        t.elapsed() < std::time::Duration::from_secs(2),
        "{:?}",
        t.elapsed()
    );
}

/// zerocopy-4: two SHT_SYMTAB_SHNDX sections claim the same table; the
/// choice is recorded with the other one as an alternative.
#[test]
fn competing_shndx_sections_are_an_inference() {
    let s = vec![
        shdr(0, 0, 0, 0, 0),
        shdr(2, 0, 0, 0, 24),
        shdr(18, 1, 0, 0, 4),
        shdr(18, 1, 0, 0, 4),
    ];
    let d = with_sections(&s, 0, &[]);
    let f = ElfFile::parse(&d).unwrap();
    let inf = f
        .inferences()
        .into_iter()
        .find(|i| i.subject == InferenceSubject::ExtendedIndexTable { table: 1 })
        .expect("inference");
    assert_eq!(inf.chosen, Choice::Section(2));
    assert_eq!(inf.alternatives.len(), 1);
    assert_eq!(inf.alternatives[0].choice, Choice::Section(3));
    // A single SHT_SYMTAB_SHNDX needs no inference.
    let d = with_sections(&s[..3], 0, &[]);
    assert!(ElfFile::parse(&d).unwrap().inferences().is_empty());
}

/// zerocopy-5: allocation-free lookups agree with the owned ones.
#[test]
fn memory_map_borrowing_api() {
    let d = file("aarch64/s00-baseline.elf");
    let f = ElfFile::parse(&d).unwrap();
    let m = f.memory_map();
    let e = f.header().entry;
    assert_eq!(m.backing_ref(e).unwrap().to_owned(), m.backing(e).unwrap());
    let code = m.bytes_at(&d, e).unwrap();
    assert_eq!(code.as_ptr(), d[0x1c10..].as_ptr());
    assert!(
        m.regions()
            .any(|r| r.flags & 1 != 0 && r.start <= e && e < r.end)
    );
    let dy = f.dynamic_with(&m);
    assert_eq!(dy.is_ok(), f.dynamic().is_ok());
}
